old_cast='for(int i=0;i<Math.min(10,cast.length());i++){JSONObject actor=cast.optJSONObject(i);if(actor==null)continue;LinearLayout person=column();person.setGravity(Gravity.CENTER_HORIZONTAL);ImageView face=new ImageView(this);face.setScaleType(ImageView.ScaleType.CENTER_CROP);GradientDrawable circle=new GradientDrawable();circle.setShape(GradientDrawable.OVAL);circle.setColor(SURFACE);face.setBackground(circle);face.setClipToOutline(true);person.addView(face,new LinearLayout.LayoutParams(dp(64),dp(64)));String photo=ContentApi.image(actor.optString("profile_path"),"w185");if(!photo.isEmpty())picture(photo,face,token);space(person,6);TextView name=text(actor.optString("name"),12,INK);name.setGravity(Gravity.CENTER);name.setSingleLine(true);name.setEllipsize(TextUtils.TruncateAt.END);person.addView(name,new LinearLayout.LayoutParams(-1,-2));TextView role=text(actor.optString("character"),11,MUTED);role.setGravity(Gravity.CENTER);role.setSingleLine(true);role.setEllipsize(TextUtils.TruncateAt.END);person.addView(role,new LinearLayout.LayoutParams(-1,-2));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(dp(100),-2);pp.setMargins(0,0,dp(8),0);people.addView(person,pp);}'
new_cast='for(int i=0;i<Math.min(12,cast.length());i++){JSONObject actor=cast.optJSONObject(i);if(actor==null)continue;int personId=actor.optInt("id");String personName=actor.optString("name");LinearLayout person=column();person.setGravity(Gravity.CENTER_HORIZONTAL);person.setPadding(dp(6),dp(6),dp(6),dp(8));person.setFocusable(personId>0);person.setClickable(personId>0);person.setContentDescription("See titles starring "+personName);person.setBackground(shape(Color.TRANSPARENT,0));person.setOnFocusChangeListener((v,f)->person.setBackground(shape(f?alphaColor(SURFACE,0xD8):Color.TRANSPARENT,f?ACCENT:0)));if(personId>0)person.setOnClickListener(v->personTitles(personId,personName));ImageView face=new ImageView(this);face.setScaleType(ImageView.ScaleType.CENTER_CROP);GradientDrawable circle=new GradientDrawable();circle.setShape(GradientDrawable.OVAL);circle.setColor(SURFACE);face.setBackground(circle);face.setClipToOutline(true);person.addView(face,new LinearLayout.LayoutParams(dp(64),dp(64)));String photo=ContentApi.image(actor.optString("profile_path"),"w185");if(!photo.isEmpty())picture(photo,face,token);space(person,6);TextView name=text(personName,12,INK);name.setGravity(Gravity.CENTER);name.setSingleLine(true);name.setEllipsize(TextUtils.TruncateAt.END);person.addView(name,new LinearLayout.LayoutParams(-1,-2));TextView role=text(actor.optString("character"),11,MUTED);role.setGravity(Gravity.CENTER);role.setSingleLine(true);role.setEllipsize(TextUtils.TruncateAt.END);person.addView(role,new LinearLayout.LayoutParams(-1,-2));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(dp(112),-2);pp.setMargins(0,0,dp(8),0);people.addView(person,pp);}'
