insert_person='''    void personTitles(int personId,String personName){\n        if(personId<=0)return;message("Loading titles starring "+personName+"…");String key=tmdbKey();io.execute(()->{try{List<Catalog.Item> titles=ContentApi.personCredits(personId,key);ui.post(()->{if(isDestroyed())return;if(titles.isEmpty()){message("No movie or series credits found for "+personName);return;}LinearLayout panel=column();panel.setPadding(dp(16),dp(12),dp(16),dp(16));panel.addView(text("Movies and series featuring "+personName,13,MUTED));space(panel,12);int columns=BuildConfig.TV?4:2;for(int i=0;i<Math.min(32,titles.size());i+=columns){LinearLayout row=new LinearLayout(this);for(int c=0;c<columns;c++){LinearLayout.LayoutParams cell=new LinearLayout.LayoutParams(0,-2,1);cell.setMargins(0,0,dp(c==columns-1?0:10),dp(12));if(i+c<titles.size())row.addView(card(titles.get(i+c),renderVersion),cell);else row.addView(new View(this),cell);}panel.addView(row);}ScrollView scroller=new ScrollView(this);scroller.setFillViewport(true);scroller.addView(panel);AlertDialog results=new AlertDialog.Builder(this).setTitle(personName).setView(scroller).setNegativeButton("Close",null).create();results.show();if(results.getWindow()!=null){results.getWindow().setBackgroundDrawable(shape(BG,0));results.getWindow().setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(28),dp(BuildConfig.TV?980:620)),Math.min(getResources().getDisplayMetrics().heightPixels-dp(56),dp(650)));}ui.post(visiblePictures);});}catch(Exception e){ui.post(()->{if(!isDestroyed())message("Could not load "+personName+"'s titles right now.");});}});\n    }\n'''
main=replace_once(main,'    void trailer(JSONObject data){',insert_person+'    void trailer(JSONObject data){','#19 person titles method')

