# Unique art choice: gather candidate art, pick the first artwork not already used on this category render.
old_loader='String apiKey=tmdbKey();io.execute(()->{String url="";try{List<Catalog.Item> examples=ContentApi.tmdbRows((task.id==-16?ContentApi.animeData(apiKey,task.type,1):ContentApi.categoryData(apiKey,task.type,task.id,1)).getJSONArray("results"),task.type,false);for(Catalog.Item item:examples){url=item.raw.optString("backdrop");if(url.isEmpty())url=item.poster;if(!url.isEmpty())break;}}catch(Exception ignored){}final String art=url;ui.post(()->{genreArtworkLoading.remove(key);if(isDestroyed())return;if(!art.isEmpty()){genreArtwork.put(key,art);if(task.token==renderVersion&&category.equals("Categories"))picture(art,task.image,task.token);ui.post(visiblePictures);}});});}'
new_loader='String apiKey=tmdbKey();io.execute(()->{List<String> candidates=new ArrayList<>();try{List<Catalog.Item> examples=ContentApi.tmdbRows((task.id==-16?ContentApi.animeData(apiKey,task.type,1):ContentApi.categoryData(apiKey,task.type,task.id,1)).getJSONArray("results"),task.type,false);for(Catalog.Item item:examples){String candidate=item.raw.optString("backdrop");if(candidate.isEmpty())candidate=item.poster;if(!candidate.isEmpty()&&!candidates.contains(candidate))candidates.add(candidate);if(candidates.size()>=10)break;}}catch(Exception ignored){}ui.post(()->{genreArtworkLoading.remove(key);if(isDestroyed())return;String art="";for(String candidate:candidates)if(!categoryArtworkUsed.contains(candidate)){art=candidate;break;}if(art.isEmpty()&&!candidates.isEmpty())art=candidates.get(Math.floorMod(task.id,candidates.size()));if(!art.isEmpty()){categoryArtworkUsed.add(art);genreArtwork.put(key,art);if(task.token==renderVersion&&category.equals("Categories"))picture(art,task.image,task.token);ui.post(visiblePictures);}});});}'
main=replace_once(main,old_loader,new_loader,'#20 unique category artwork')

# ContentApi exact person combined credits (#19).
api=replace_once(api,'    static JSONArray providers(String key,String type,String region) throws Exception {', '''    static List<Catalog.Item> personCredits(int personId,String key) throws Exception {\n        if(personId<=0)throw new IOException("Invalid person ID");JSONArray cast=tmdb("/person/"+personId+"/combined_credits",key,"").optJSONArray("cast");if(cast==null)return new ArrayList<>();List<JSONObject> raw=new ArrayList<>();for(int i=0;i<cast.length();i++){JSONObject credit=cast.optJSONObject(i);if(credit!=null&&!credit.optBoolean("adult")&&(credit.optString("media_type").equals("movie")||credit.optString("media_type").equals("tv")))raw.add(credit);}Collections.sort(raw,(a,b)->Double.compare(b.optDouble("popularity",0),a.optDouble("popularity",0)));JSONArray ordered=new JSONArray();HashSet<String> seen=new HashSet<>();for(JSONObject credit:raw){String id=credit.optString("media_type")+":"+credit.optLong("id");if(seen.add(id))ordered.put(credit);if(ordered.length()>=40)break;}return tmdbRows(ordered,"movie",false);\n    }\n    static JSONArray providers(String key,String type,String region) throws Exception {''','#19 ContentApi person credits')

